        s=logfile.read_text()
        def number(pattern):
            m=re.search(pattern,s,re.I)
            if not m: raise SystemExit('Missing baseline output: '+pattern)
            value=float(m[1])
            if not math.isfinite(value): raise SystemExit('Nonfinite baseline output')
            return value
